class GameEngine{constructor(e,t,s){this.sessionCode=e,this.gameType=t,this.config=s,this.isPlaying=!0,this.startTime=Date.now(),this.state={},this.selectedPrize=null,this.result=null}getCompletionTime(){return Math.floor((Date.now()-this.startTime)/1e3)}async endGame(e){this.isPlaying=!1,this.selectedPrize=e,this.result={session_code:this.sessionCode,selected_prize:e,completion_time_seconds:this.getCompletionTime(),timestamp:(new Date).toISOString()};try{const e=await fetch("/api/game/result",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(this.result)});return await e.json()}catch(e){return console.error("❌ Error saving game result:",e),{success:!1,error:e.message}}}async shareResult(){try{const e=await fetch(`/api/game/${this.sessionCode}/share`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({prize_index:this.selectedPrize})});if(navigator.share)await navigator.share({title:"GiftBox Game",text:`I just won prize #${this.selectedPrize+1}! 🎁`,url:`${window.location.origin}/play/${this.sessionCode}`});else{const e=`${window.location.origin}/play/${this.sessionCode}`;navigator.clipboard.writeText(e),alert("Link copied to clipboard!")}return e.json()}catch(e){console.error("❌ Error sharing:",e)}}}console.log("✅ Game Engine loaded");